}.cmd-field { display: flex; align-items: center; gap: 10px; min-width: 330px; height: 54px; padding: 0px 18px; background: rgb(255, 255, 255); border: 2px solid var(--dark); border-radius: 10px; cursor: pointer; text-align: left; font-family: var(--mono); font-size: 16px; color: var(--dark); }.cmd-field .pfx { color: rgb(154, 160, 166); }.cmd-field .cmd { flex: 1 1 0%; }.cmd-field .hint-copy { font-family: var(--font); font-size: 11px; font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase; color: rgb(154, 160, 166); }.cmd-field:hover { background: var(--n50); }.cmd-field.copied { border-color: var(--blue); }.cmd-field.copied .hint-copy { color: var(--blue); }.start-note { margin-top: 16px; font-size: 13px; color: var(--n600); }.start-note strong { color: var(--dark); }.start-next { display: none; margin-top: 20px; }.start-next.on { display: block; }.shot { margin-top: 54px; border: 1px solid var(--n300); border-radius: 14px; overflow: hidden; box-shadow: var(--shadow-md); background: rgb(255, 255, 255); }.shot-bar { display: flex; align-items: center; gap: 8px; padding: 10px 14px; background: var(--n100); border-bottom: 1px solid var(--n300); }.shot-bar .tl { width: 10px; height: 10px; border-radius: 50%; }.shot-bar .tl.r { background: rgb(255, 95, 87); }.shot-bar .tl.y { background: rgb(254, 188, 46); }.shot-bar .tl.g { background: rgb(40, 200, 64); }.shot-bar .shot-url { margin-left: 12px; font-size: 11px; color: var(--n600); }.shot-tabs { display: flex; justify-content: center; gap: 30px; padding: 13px; border-bottom: 1px solid var(--n200); font-size: 12px; color: var(--n600); }.shot-tabs .on { color: var(--dark); font-weight: 600; }.shot-tabs .off { color: rgb(195, 198, 204); }.shot-cols { display: grid; grid-template-columns: 1fr 1.5fr 1fr; gap: 14px; padding: 16px; background: var(--n50); }.shot-card { padding: 14px; background: rgb(255, 255, 255); border: 1px solid var(--n300); border-radius: 10px; font-size: 11px; color: var(--n600); }.shot-car