lm-insp-ta--sys { min-height: 260px; }.llm-insp-ta:focus { outline: none; border-color: rgb(161, 161, 170); box-shadow: rgba(161, 161, 170, 0.16) 0px 0px 0px 3px; }.llm-insp-raw { margin: 0px; padding: 10px 12px; max-height: 260px; overflow: auto; font-family: var(--mono); font-size: 11.5px; line-height: 1.65; color: rgb(63, 63, 70); background: rgb(250, 250, 250); border: 1px solid rgb(238, 238, 238); border-radius: 8px; white-space: pre-wrap; word-break: break-word; }.llm-insp-ft { display: flex; align-items: center; gap: 10px; padding: 12px 20px; border-top: 1px solid rgb(238, 238, 238); background: rgb(255, 255, 255); }.llm-insp-note { flex: 1 1 0%; font-size: 11.5px; color: rgb(113, 113, 122); }.llm-insp-btn { padding: 7px 14px; font-size: 12.5px; font-weight: 500; color: rgb(24, 24, 27); background: rgb(255, 255, 255); border: 1px solid rgb(228, 228, 231); border-radius: 8px; cursor: pointer; }.llm-insp-btn:hover { background: rgb(250, 250, 250); }.llm-insp-btn.primary { color: rgb(255, 255, 255); background: rgb(24, 24, 27); border-color: rgb(24, 24, 27); }.llm-insp-btn.primary:hover { background: rgb(39, 39, 42); }.llm-insp-btn:disabled { opacity: 0.55; cursor: default; }@media (max-width: 720px) {
